deepml vfx 0.3
module corpus.deepml_vfx.example_03251
policy deterministic
policy no_network
effect Effect03251 {
  coupled simulation PortalSim seed 3251 { fluid: Energy cloth: Veil particles: Sparks }
  procedural operator Distort(time, portal_state) differentiable
  cache PortalCache6 interval 0s..10s step 1/60s hash sha256("cache:03251")
  bind scene PortalScene4
  bind timeline PortalSequence1
  render_graph { Sim -> Lighting -> Distortion -> Composite }
  composite multipass [SceneColor, PortalGlow, Distortion, Atmosphere]
}

